use vstd::prelude::*;

verus! {
    fn copy(a: &Vec<u64>) -> (b: Vec<u64>)
        requires
            a.len() <= 100, // The input vector's length must be at most 100
        ensures
            b.len() == a.len() // The output vector must have the same length as the input
            && forall|i: nat| (i < a.len() as nat) ==> (b[i as usize] == a[i as usize]) // Each element in b must equal the corresponding element in a
    {
        let mut b: Vec<u64> = Vec::new();
        b.resize(a.len(), 0); // Initialize b with the same length as a

        let mut idx: usize = 0;
        while idx < a.len()
            invariant
                idx <= a.len(),
                b.len() == a.len(),
                forall|i: nat| (i < idx as nat) ==> (b[i as usize] == a[i as usize]), // Elements copied so far
            decreases a.len() - idx,
        {
            b[idx] = a[idx]; // Copy the element from a to b
            idx = idx + 1; // Move to the next index
        }
        b // Return the copied vector
    }
}

